def smartscraper(user_prompt, website_url, options=None, **_extra):
    import json, os, datetime, time, hashlib
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0192000" if __import__("os").path.isdir("./environment_mix/0192000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(project_id, api_key_id, endpoint, status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _iso_day(ts):
        return ts[:10] if isinstance(ts, str) and len(ts) >= 10 else None

    def _normalize_url(u):
        if not isinstance(u, str) or not u.strip():
            return None, None, "website_url must be a non-empty string"
        u = u.strip()
        try:
            sp = urlsplit(u)
        except Exception:
            return None, None, "website_url is not a valid URL"
        if sp.scheme.lower() not in ("http", "https"):
            return None, None, "website_url scheme must be http or https"
        if not sp.netloc:
            return None, None, "website_url must include a host"
        scheme = sp.scheme.lower()
        host = sp.hostname.lower() if sp.hostname else ""
        port = sp.port
        if (scheme == "http" and port == 80) or (scheme == "https" and port == 443):
            port = None
        netloc = host + (f":{port}" if port else "")
        path = sp.path or "/"
        canonical = urlunsplit((scheme, netloc, path, sp.query or "", ""))
        return canonical, host, None

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]

    def _resolve_auth_context():
        projects = _load("projects.json")
        keys = _load("api_keys.json")
        if not isinstance(projects, list): projects = []
        if not isinstance(keys, list): keys = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and p.get("id")}
        for k in keys:
            if not isinstance(k, dict): 
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            return p, k
        for p in projects:
            if isinstance(p, dict) and p.get("status") == "active" and p.get("id"):
                return p, None
        return None, None

    def _enforce_limits(project_id):
        projects = _load("projects.json")
        runs = _load("runs.json")
        if not isinstance(projects, list): projects = []
        if not isinstance(runs, list): runs = []
        p = next((x for x in projects if isinstance(x, dict) and x.get("id") == project_id), None)
        if not p:
            return False, _err("NOT_FOUND", "Project not found")
        if p.get("status") != "active":
            return False, _err("UNAUTHORIZED", "Project is not active")
        drq = p.get("daily_run_quota")
        dpq = p.get("daily_page_fetch_quota")
        mcr = p.get("max_concurrent_runs")
        if not isinstance(drq, int) or drq < 0:
            return False, _err("VALIDATION_ERROR", "Project daily_run_quota is invalid")
        if not isinstance(dpq, int) or dpq < 0:
            return False, _err("VALIDATION_ERROR", "Project daily_page_fetch_quota is invalid")
        if not isinstance(mcr, int) or mcr < 1:
            return False, _err("VALIDATION_ERROR", "Project max_concurrent_runs is invalid")

        today = _iso_day(now)
        todays_runs = [r for r in runs if isinstance(r, dict) and r.get("project_id") == project_id and _iso_day(r.get("created_at")) == today]
        if len(todays_runs) >= drq:
            return False, _err("QUOTA_EXCEEDED", "Daily run quota exceeded", quota="daily_run_quota", limit=drq, used=len(todays_runs))

        artifacts = _load("run_artifacts.json")
        if not isinstance(artifacts, list): artifacts = []
        run_ids_today = {r.get("id") for r in todays_runs if r.get("id")}
        page_fetches = [a for a in artifacts if isinstance(a, dict) and a.get("run_id") in run_ids_today and a.get("artifact_type") == "page_fetch" and _iso_day(a.get("created_at")) == today]
        if len(page_fetches) >= dpq:
            return False, _err("QUOTA_EXCEEDED", "Daily page fetch quota exceeded", quota="daily_page_fetch_quota", limit=dpq, used=len(page_fetches))

        running = [r for r in runs if isinstance(r, dict) and r.get("project_id") == project_id and r.get("status") == "running"]
        at_capacity = len(running) >= mcr
        return True, {"at_capacity": at_capacity}

    # Validate inputs
    if not isinstance(user_prompt, str) or not user_prompt.strip():
        _log_request(None, None, "smartscraper", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_prompt is required and must be a non-empty string")
    if not isinstance(website_url, str) or not website_url.strip():
        _log_request(None, None, "smartscraper", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "website_url is required and must be a non-empty string")
    if options is None:
        options = {}
    if not isinstance(options, dict):
        _log_request(None, None, "smartscraper", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "options must be an object if provided")

    canonical_url, domain, uerr = _normalize_url(website_url)
    if uerr:
        _log_request(None, None, "smartscraper", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", uerr)

    project, api_key = _resolve_auth_context()
    if not project:
        _log_request(None, None, "smartscraper", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized project context available")

    ok, lim = _enforce_limits(project.get("id"))
    if not ok:
        _log_request(project.get("id"), api_key.get("id") if api_key else None, "smartscraper", "error", lim["error"]["code"])
        return lim

    runs = _load("runs.json")
    if not isinstance(runs, list): runs = []
    run_id = _new_id("run")
    status = "queued" if lim.get("at_capacity") else "running"
    run = {
        "id": run_id,
        "project_id": project.get("id"),
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": "smartscraper",
        "user_prompt": user_prompt.strip(),
        "website_url": website_url.strip(),
        "input_options": options,
        "status": status,
        "error_code": None,
        "error_message": None,
        "output_payload": None,
        "output_text": None,
        "tokens_input": None,
        "tokens_output": None,
        "cost_usd": None,
        "queued_at": now if status == "queued" else None,
        "started_at": now if status == "running" else None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    runs.append(run)

    # Upsert web_resource and page_fetch artifact
    web_resources = _load("web_resources.json")
    if not isinstance(web_resources, list): web_resources = []
    wr = next((w for w in web_resources if isinstance(w, dict) and w.get("canonical_url") == canonical_url), None)
    if wr:
        wr["raw_url"] = website_url.strip()
        wr["domain"] = domain
        wr["last_http_status"] = 200
        wr["last_fetched_at"] = now
        wr["updated_at"] = now
    else:
        wr = {
            "id": _new_id("wr"),
            "canonical_url": canonical_url,
            "raw_url": website_url.strip(),
            "domain": domain,
            "content_type": "text/html",
            "robots_allowed": None,
            "last_http_status": 200,
            "last_fetched_at": now,
            "created_at": now,
            "updated_at": now,
        }
        web_resources.append(wr)

    artifacts = _load("run_artifacts.json")
    if not isinstance(artifacts, list): artifacts = []
    page_fetch = {
        "id": _new_id("art"),
        "run_id": run_id,
        "web_resource_id": wr.get("id"),
        "artifact_type": "page_fetch",
        "sequence": 0,
        "status": "ready",
        "http_status": 200,
        "title": None,
        "snippet": None,
        "content_text": None,
        "content_json": None,
        "source_hash": hashlib.sha256(canonical_url.encode("utf-8")).hexdigest(),
        "created_at": now,
        "updated_at": now,
    }
    # ensure uniqueness for sequence if needed
    if any(isinstance(a, dict) and a.get("run_id") == run_id and a.get("artifact_type") == "page_fetch" and a.get("sequence") == 0 for a in artifacts):
        page_fetch["sequence"] = 1
    artifacts.append(page_fetch)

    # If running, generate extraction output deterministically (offline)
    extraction_art = None
    if run["status"] == "running":
        extracted = {
            "source": {"canonical_url": canonical_url},
            "prompt": user_prompt.strip(),
            "extracted_at": now,
            "data": {
                "title": canonical_url,
                "summary": f"Extraction placeholder for {domain}",
            },
        }
        run["output_payload"] = extracted
        run["status"] = "succeeded"
        run["finished_at"] = now
        run["updated_at"] = now

        extraction_art = {
            "id": _new_id("art"),
            "run_id": run_id,
            "web_resource_id": wr.get("id"),
            "artifact_type": "extraction",
            "sequence": 0,
            "status": "ready",
            "http_status": None,
            "title": None,
            "snippet": None,
            "content_text": None,
            "content_json": extracted,
            "source_hash": page_fetch.get("source_hash"),
            "created_at": now,
            "updated_at": now,
        }
        # ensure unique(run_id, artifact_type, sequence)
        if any(isinstance(a, dict) and a.get("run_id") == run_id and a.get("artifact_type") == "extraction" and a.get("sequence") == 0 for a in artifacts):
            extraction_art["sequence"] = 1
        artifacts.append(extraction_art)

    _save("runs.json", runs)
    _save("web_resources.json", web_resources)
    _save("run_artifacts.json", artifacts)
    if api_key:
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            for k in keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
            _save("api_keys.json", keys)

    _log_request(project.get("id"), api_key.get("id") if api_key else None, "smartscraper", "ok", None)
    return {
        "run": run,
        "output": run.get("output_payload") if run.get("output_payload") is not None else {"status": run.get("status")},
        "artifacts": [a for a in artifacts if isinstance(a, dict) and a.get("run_id") == run_id and a.get("artifact_type") in ("page_fetch", "extraction")],
    }

def list_runs(project_id=None, tool_name=None, status=None, website_url=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0192000" if __import__("os").path.isdir("./environment_mix/0192000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(project_id2, api_key_id, endpoint, status2, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "project_id": project_id2,
            "api_key_id": api_key_id,
            "status": status2,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_iso(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, "timestamp must be an ISO-8601 string"
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1]
        try:
            return datetime.datetime.fromisoformat(s2), None
        except Exception:
            return None, "timestamp must be ISO-8601"

    def _resolve_auth_context():
        # Ambient auth: require at least one active key+project OR active project
        projects = _load("projects.json")
        keys = _load("api_keys.json")
        if not isinstance(projects, list): projects = []
        if not isinstance(keys, list): keys = []
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and p.get("id")}
        for k in keys:
            if not isinstance(k, dict): 
                continue
            if k.get("status") != "active":
                continue
            p = proj_by_id.get(k.get("project_id"))
            if p and p.get("status") == "active":
                return p, k
        for p in projects:
            if isinstance(p, dict) and p.get("status") == "active" and p.get("id"):
                return p, None
        return None, None

    # Validate filters
    if project_id is not None and (not isinstance(project_id, str) or not project_id.strip()):
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string if provided")
    if tool_name is not None and tool_name not in ("markdownify", "smartscraper", "searchscraper"):
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tool_name is invalid")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid")
    if website_url is not None and (not isinstance(website_url, str) or not website_url.strip()):
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "website_url must be a non-empty string if provided")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string if provided")

    ca, e1 = _parse_iso(created_after)
    if e1:
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"created_after {e1}")
    cb, e2 = _parse_iso(created_before)
    if e2:
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"created_before {e2}")
    if ca and cb and ca > cb:
        _log_request(None, None, "list_runs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    project_ctx, api_key = _resolve_auth_context()
    if not project_ctx:
        _log_request(None, None, "list_runs", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized project context available")

    effective_project_id = project_id.strip() if isinstance(project_id, str) and project_id.strip() else project_ctx.get("id")

    # If an API key exists, restrict to its project unless explicitly same
    if api_key and effective_project_id != api_key.get("project_id"):
        _log_request(project_ctx.get("id"), api_key.get("id"), "list_runs", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not authorized for the requested project")

    runs = _load("runs.json")
    if not isinstance(runs, list): runs = []

    # Apply cursor as "created_at|id" exclusive
    cursor_created = None
    cursor_id = None
    if cursor:
        # Accept either "ts|id" or just id; if just id, locate it and use its created_at
        if "|" in cursor:
            parts = cursor.split("|", 1)
            cursor_created = parts[0]
            cursor_id = parts[1]
        else:
            cursor_id = cursor
            rcur = next((r for r in runs if isinstance(r, dict) and r.get("id") == cursor_id), None)
            cursor_created = rcur.get("created_at") if rcur else None

    def _created_dt(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    out = []
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != effective_project_id:
            continue
        if tool_name and r.get("tool_name") != tool_name:
            continue
        if status and r.get("status") != status:
            continue
        if website_url and r.get("website_url") != website_url.strip():
            continue
        rcdt = _created_dt(r)
        if ca and rcdt and rcdt < ca:
            continue
        if cb and rcdt and rcdt > cb:
            continue
        # cursor: return strictly older than cursor record in newest-first ordering
        if cursor_created:
            try:
                cdt = datetime.datetime.fromisoformat(cursor_created[:-1] if cursor_created.endswith("Z") else cursor_created)
            except Exception:
                cdt = None
            if cdt and rcdt:
                if rcdt > cdt:
                    continue
                if rcdt == cdt and cursor_id and r.get("id") >= cursor_id:
                    continue
        out.append(r)

    # newest-first
    out.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)
    total = len(out)
    page = out[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"{last.get('created_at')}|{last.get('id')}"

    if api_key:
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            for k in keys:
                if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
            _save("api_keys.json", keys)

    _log_request(effective_project_id, api_key.get("id") if api_key else None, "list_runs", "ok", None)
    return {
        "runs": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "project_id": effective_project_id,
        },
    }

def get_run(run_id, include_artifacts=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0192000" if __import__("os").path.isdir("./environment_mix/0192000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, project_id=None, run_id_val=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get_run",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "api_key_id": api_key_id,
            "project_id": project_id,
            "run_id": run_id_val,
        }
        if error:
            entry["error"] = error
        logs.append(entry)
        _save("request_logs.json", logs)

    try:
        if not isinstance(run_id, str) or not run_id.strip():
            _log("error", error={"code": "VALIDATION_ERROR", "message": "run_id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "run_id must be a non-empty string")
        if include_artifacts is None:
            include_artifacts = False
        if not isinstance(include_artifacts, bool):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "include_artifacts must be a boolean"})
            return _err("VALIDATION_ERROR", "include_artifacts must be a boolean")

        runs = _load("runs.json")
        if not isinstance(runs, list):
            runs = []
        run = next((r for r in runs if isinstance(r, dict) and r.get("id") == run_id), None)
        if not run:
            _log("error", error={"code": "NOT_FOUND", "message": "Run not found"})
            return _err("NOT_FOUND", "Run not found")

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        project = next((p for p in projects if isinstance(p, dict) and p.get("id") == run.get("project_id")), None)
        if not project:
            _log("error", error={"code": "NOT_FOUND", "message": "Project not found for run"})
            return _err("NOT_FOUND", "Project not found for run")

        # Ambient auth: if a run has api_key_id, require it to still exist and be active to view.
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        used_key_id = run.get("api_key_id")
        if used_key_id is not None:
            key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == used_key_id), None)
            if not key or key.get("status") != "active":
                _log("error", api_key_id=used_key_id, project_id=project.get("id"), run_id_val=run_id,
                     error={"code": "NOT_FOUND", "message": "Run not found"})
                return _err("NOT_FOUND", "Run not found")

        # Touch last_used_at for associated key (if any) to reflect access.
        if used_key_id is not None:
            changed = False
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == used_key_id and k.get("status") == "active":
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    changed = True
                    break
            if changed:
                _save("api_keys.json", api_keys)

        out = {"run": run}

        if include_artifacts:
            artifacts = _load("run_artifacts.json")
            if not isinstance(artifacts, list):
                artifacts = []
            compact = []
            for a in artifacts:
                if not isinstance(a, dict):
                    continue
                if a.get("run_id") != run_id:
                    continue
                compact.append({
                    "id": a.get("id"),
                    "artifact_type": a.get("artifact_type"),
                    "sequence": a.get("sequence"),
                    "status": a.get("status"),
                    "web_resource_id": a.get("web_resource_id"),
                    "http_status": a.get("http_status"),
                    "title": a.get("title"),
                    "snippet": a.get("snippet"),
                    "created_at": a.get("created_at"),
                    "updated_at": a.get("updated_at"),
                })
            compact.sort(key=lambda x: (x.get("artifact_type") or "", x.get("sequence") if isinstance(x.get("sequence"), int) else 0))
            out["artifacts"] = compact
            out["artifacts_count"] = len(compact)

        _log("ok", api_key_id=used_key_id, project_id=project.get("id"), run_id_val=run_id)
        return out
    except Exception as e:
