        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def cancel_run(run_id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0192000" if __import__("os").path.isdir("./environment_mix/0192000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, api_key_id=None, project_id=None, run_id_val=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "cancel_run",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "api_key_id": api_key_id,
            "project_id": project_id,
            "run_id": run_id_val,
        }
        if error:
            entry["error"] = error
        logs.append(entry)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(run_id, str) or not run_id.strip():
        _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "run_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "run_id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "reason must be a string"})
        return _err("VALIDATION_ERROR", "reason must be a string")

    # Load run
    runs = _load("runs.json")
    if not isinstance(runs, list):
        runs = []
    run = None
    idx = None
    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == run_id:
            run = r
            idx = i
            break
    if run is None:
        _log("error", run_id_val=run_id, error={"code": "NOT_FOUND", "message": "Run not found"})
        return _err("NOT_FOUND", "Run not found")

    api_key_id = run.get("api_key_id")
    project_id = run.get("project_id")

    # Ambient authentication / visibility:
    # This tool has no credential param, so callers are already authenticated.
    # We must still ensure the run references a real project, and if it references an API key, that key exists.
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project_row = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            project_row = p
            break
    if project_row is None:
        _log("error", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id,
             error={"code": "UNAUTHORIZED", "message": "No valid project context found for this run"})
        return _err("UNAUTHORIZED", "No valid project context found for this run")

    if api_key_id is not None:
        api_keys = _load("api_keys.json")
        if not isinstance(api_keys, list):
            api_keys = []
        key_row = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                key_row = k
                break
        # If the run claims it was created with a key that no longer exists, refuse (visibility cannot be established).
        if key_row is None:
            _log("error", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id,
                 error={"code": "UNAUTHORIZED", "message": "Run is not visible to any active credential context"})
            return _err("UNAUTHORIZED", "Run is not visible to any active credential context")

    # Lifecycle: only queued/running can be cancelled; terminal states are idempotent success (already cancelled)
    # or invalid transition (succeeded/failed cannot be cancelled per business rule).
    status = run.get("status")
    allowed_from = ("queued", "running")
    if status == "cancelled":
        # Idempotent: already cancelled, return the current metadata
        _log("ok", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id)
        return {"run": run}
    if status not in allowed_from:
        # Provide rule-specific message
        msg = "Business rule: cancellation is only allowed when run.status is 'queued' or 'running'; terminal runs cannot be cancelled."
        _log("error", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id,
             error={"code": "INVALID_TRANSITION", "message": msg, "current_status": status})
        return _err("INVALID_TRANSITION", msg, current_status=status)

    # Apply transition
    run["status"] = "cancelled"
    run["error_code"] = "client_cancelled"
    if reason is not None and reason.strip():
        run["error_message"] = reason
    else:
        # Keep existing error_message if present; otherwise provide a default
        if not run.get("error_message"):
            run["error_message"] = "Cancelled by client."

    # timestamps
    run["updated_at"] = now
    run["finished_at"] = now
    # If it was queued and never started, do not force started_at; keep as-is.

    runs[idx] = run
    _save("runs.json", runs)

    _log("ok", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id)
    return {"run": run}

def list_run_artifacts(run_id, artifact_type=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0192000" if __import__("os").path.isdir("./environment_mix/0192000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, api_key_id=None, project_id=None, run_id_val=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "list_run_artifacts",
            "timestamp": now,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "api_key_id": api_key_id,
            "project_id": project_id,
            "run_id": run_id_val,
        }
        if error:
            entry["error"] = error
        logs.append(entry)
        _save("request_logs.json", logs)

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        # Cursor is documented as opaque; to be robust, accept:
        # - our base64(json{offset:int})
        # - a plain integer string (legacy)
        # - any other string treated as offset=0
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return 0
        cur = cur.strip()
        if cur.isdigit():
            try:
                return max(0, int(cur))
            except Exception:
                return 0
        try:
            pad = "=" * (-len(cur) % 4)
            data = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(data.decode("utf-8"))
            off = obj.get("offset", 0)
            if isinstance(off, int) and off >= 0:
                return off
            return 0
        except Exception:
            return 0

    if not isinstance(run_id, str) or not run_id.strip():
        _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "run_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "run_id must be a non-empty string")

    if artifact_type is not None:
        if not isinstance(artifact_type, str) or artifact_type not in ("page_fetch", "markdown", "extraction", "search_result"):
            _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "artifact_type is invalid"})
            return _err("VALIDATION_ERROR", "artifact_type is invalid")

    if status is not None:
        if not isinstance(status, str) or status not in ("pending", "ready", "failed"):
            _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "status is invalid"})
            return _err("VALIDATION_ERROR", "status is invalid")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "limit must be an integer"})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("error", run_id_val=run_id, error={"code": "VALIDATION_ERROR", "message": "limit must be between 1 and 200"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    runs = _load("runs.json")
    if not isinstance(runs, list):
        runs = []
    run = next((r for r in runs if isinstance(r, dict) and r.get("id") == run_id), None)
    if not run:
        _log("error", run_id_val=run_id, error={"code": "NOT_FOUND", "message": "Run not found"})
        return _err("NOT_FOUND", "Run not found")

    api_key_id = run.get("api_key_id")
    project_id = run.get("project_id")

    # Visibility: same relaxed ambient auth approach: run is visible if its referenced entities exist consistently.
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    if api_key_id is not None:
        k = next((kk for kk in api_keys if isinstance(kk, dict) and kk.get("id") == api_key_id), None)
        if not k:
            _log("error", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id,
                 error={"code": "NOT_FOUND", "message": "Run not visible"})
            return _err("NOT_FOUND", "Run not visible to the calling API key")
        kp = k.get("project_id")
        if kp and project_id and kp != project_id:
            _log("error", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id,
                 error={"code": "NOT_FOUND", "message": "Run not visible"})
            return _err("NOT_FOUND", "Run not visible to the calling API key")
    else:
        if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
            _log("error", api_key_id=None, project_id=project_id, run_id_val=run_id,
                 error={"code": "NOT_FOUND", "message": "Run not visible"})
            return _err("NOT_FOUND", "Run not visible to the calling API key")

    artifacts = _load("run_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    filtered = []
    for a in artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("run_id") != run_id:
            continue
        if artifact_type is not None and a.get("artifact_type") != artifact_type:
            continue
        if status is not None and a.get("status") != status:
            continue
        filtered.append(a)

    # Stable ordering: artifact_type, sequence, id (so cursor offset works)
    def _k(a):
        at = a.get("artifact_type") or ""
        seq = a.get("sequence")
        if not isinstance(seq, int):
            seq = 0
        aid = a.get("id") or ""
        return (at, seq, aid)

    filtered.sort(key=_k)

    offset = _decode_cursor(cursor)
    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    _log("ok", api_key_id=api_key_id, project_id=project_id, run_id_val=run_id)
    return {
        "artifacts": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_web_resource(web_resource_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0192000" if __import__("os").path.isdir("./environment_mix/0192000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, project_id=None, web_resource_id_val=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get_web_resource",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "api_key_id": api_key_id,
            "project_id": project_id,
            "web_resource_id": web_resource_id_val,
        }
        if error:
            entry["error"] = error
        logs.append(entry)
        _save("request_logs.json", logs)

    if not isinstance(web_resource_id, str) or not web_resource_id.strip():
        _log("error", web_resource_id_val=web_resource_id, error={"code": "VALIDATION_ERROR", "message": "web_resource_id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "web_resource_id must be a non-empty string")

    resources = _load("web_resources.json")
    if not isinstance(resources, list):
        resources = []
    res = next((w for w in resources if isinstance(w, dict) and w.get("id") == web_resource_id), None)
    if not res:
        _log("error", web_resource_id_val=web_resource_id, error={"code": "NOT_FOUND", "message": "Web resource not found"})
        return _err("NOT_FOUND", "Web resource not found")

    # Visibility: if referenced by any run_artifact, ensure at least one referencing run exists and is owned by a valid project.
    # Do NOT require that the initiating api key is still active (revocation should not hide historical data).
    artifacts = _load("run_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    runs = _load("runs.json")
    if not isinstance(runs, list):
        runs = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    referencing_run_ids = []
    for a in artifacts:
        if isinstance(a, dict) and a.get("web_resource_id") == web_resource_id and isinstance(a.get("run_id"), str):
            referencing_run_ids.append(a.get("run_id"))

    resolved_project_id = None
    if referencing_run_ids:
        for rid in referencing_run_ids:
            r = next((rr for rr in runs if isinstance(rr, dict) and rr.get("id") == rid), None)
            if not r:
                continue
            pid = r.get("project_id")
            if pid and any(isinstance(p, dict) and p.get("id") == pid for p in projects):
                resolved_project_id = pid
                break
        if resolved_project_id is None:
            _log("error", project_id=None, web_resource_id_val=web_resource_id,
                 error={"code": "UNAUTHORIZED", "message": "Web resource is not visible to the calling context"})
            return _err("UNAUTHORIZED", "Web resource is not visible to the calling context")

    _log("ok", project_id=resolved_project_id, web_resource_id_val=web_resource_id)
    return {"web_resource": res}
